'use strict';

const http = require('http');
const path = require('path');
const fs = require('fs');
const { spawn } = require('child_process');

const HOST = '127.0.0.1';
const PORT = 3000;
const CLI_EXECUTABLE = 'node';
const CLI_CWD = path.resolve(__dirname, '../release-manager-v2');
const AUDIT_PATH = path.join(__dirname, 'audit-log.jsonl');
const COLLAPSIBLE_OUTPUT_THRESHOLD = 2000;

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderTextWithLinks(value) {
  const text = String(value);
  const urlPattern = /https?:\/\/[^\s<>]+/g;
  let result = '';
  let position = 0;
  let match;

  while ((match = urlPattern.exec(text)) !== null) {
    result += escapeHtml(text.slice(position, match.index));
    const url = match[0];
    result += `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(url)}</a>`;
    position = match.index + url.length;
  }

  result += escapeHtml(text.slice(position));
  return result;
}

function humanizeKey(key) {
  return String(key)
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[_-]+/g, ' ')
    .replace(/^./, character => character.toUpperCase());
}

function renderValue(value) {
  if (value === null) return '<span class="null">null</span>';
  if (value === undefined) return '<em>Not provided by status output</em>';

  if (Array.isArray(value)) {
    if (value.length === 0) return '<span class="empty">[]</span>';
    return `<ol>${value.map(item => `<li>${renderValue(item)}</li>`).join('')}</ol>`;
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value);
    if (entries.length === 0) return '<span class="empty">{}</span>';
    return `<dl>${entries.map(([key, item]) =>
      `<dt>${escapeHtml(humanizeKey(key))}</dt><dd>${renderValue(item)}</dd>`
    ).join('')}</dl>`;
  }

  if (typeof value === 'string') return renderTextWithLinks(value);
  return escapeHtml(String(value));
}

function normalizeKey(key) {
  return String(key).replace(/[^a-z0-9]/gi, '').toLowerCase();
}

function findStatusValue(root, candidateKeys) {
  const wanted = new Set(candidateKeys.map(normalizeKey));
  const visited = new Set();

  function visit(value) {
    if (!value || typeof value !== 'object' || visited.has(value)) return undefined;
    visited.add(value);

    for (const [key, child] of Object.entries(value)) {
      if (wanted.has(normalizeKey(key))) return child;
    }
    for (const child of Object.values(value)) {
      const found = visit(child);
      if (found !== undefined) return found;
    }
    return undefined;
  }

  return visit(root);
}

function readRecentActivity() {
  let contents;
  try {
    contents = fs.readFileSync(AUDIT_PATH, 'utf8');
  } catch (error) {
    if (error && error.code === 'ENOENT') return null;
    return { unavailable: true };
  }

  const lines = contents.split(/\n/);
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    if (lines[index].length === 0) continue;

    let entry;
    try {
      entry = JSON.parse(lines[index]);
    } catch (_error) {
      continue;
    }

    const args = entry && entry.command && entry.command.arguments;
    const result = entry && entry.result;
    if (!Array.isArray(args) || typeof args[1] !== 'string' ||
        typeof entry.timestamp !== 'string' || !result ||
        !Object.prototype.hasOwnProperty.call(result, 'exitCode')) {
      continue;
    }

    return {
      action: humanizeKey(args[1]),
      exitCode: result.exitCode,
      timestamp: entry.timestamp
    };
  }

  return null;
}

function renderRecentActivity() {
  const activity = readRecentActivity();
  if (activity === null) {
    return '<div class="activity activity-empty" role="status"><span class="activity-label">Recent activity</span><span>No actions recorded yet</span></div>';
  }
  if (activity.unavailable === true) {
    return '<div class="activity activity-unavailable" role="status"><span class="activity-label">Recent activity</span><span>Recent activity unavailable</span></div>';
  }

  const outcomeClass = activity.exitCode === 0 ? 'activity-success' : 'activity-failure';
  return `<div class="activity ${outcomeClass}" role="status">
    <span class="activity-label">Recent activity</span>
    <span class="activity-item"><strong>Action:</strong> ${escapeHtml(activity.action)}</span>
    <span class="activity-item"><strong>Exit code:</strong> ${activity.exitCode === null ? 'null' : escapeHtml(activity.exitCode)}</span>
    <span class="activity-item"><strong>Timestamp:</strong> <time datetime="${escapeHtml(activity.timestamp)}">${escapeHtml(activity.timestamp)}</time></span>
  </div>`;
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  :root {
    color-scheme: light dark;
    --page: #f4f7fb;
    --surface: #ffffff;
    --surface-subtle: #eef3f8;
    --text: #172033;
    --muted: #5b6577;
    --border: #ccd5e1;
    --link: #1559b7;
    --focus: #2563eb;
    --success: #18794e;
    --success-soft: #e5f6ed;
    --warning: #9a5b00;
    --warning-soft: #fff3d6;
    --danger: #b42332;
    --danger-soft: #fdebed;
    --stdout: #176b45;
    --stdout-soft: #edf9f2;
    --stderr: #a2303d;
    --stderr-soft: #fff0f1;
    --shadow: 0 8px 24px rgba(26, 39, 61, .08);
  }

  * { box-sizing: border-box; }
  html { background: var(--page); }
  body {
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 1.25rem 3rem;
    font: 16px/1.55 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    color: var(--text);
    background: var(--page);
  }
  a { color: var(--link); text-underline-offset: .18em; }
  a:hover { text-decoration-thickness: .14em; }
  a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible {
    outline: 3px solid var(--focus);
    outline-offset: 2px;
  }
  .site-header {
    position: relative;
    margin: 0 -1.25rem 2rem;
    padding: 1rem 1.25rem;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    box-shadow: var(--shadow);
  }
  nav {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .5rem 1.25rem;
    margin-bottom: .85rem;
  }
  nav a { font-weight: 700; text-decoration: none; }
  .brand { margin-right: auto; color: var(--text); font-size: 1.05rem; }
  .activity {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: .4rem 1rem;
    padding: .7rem .85rem;
    border: 1px solid var(--border);
    border-left: .3rem solid var(--muted);
    border-radius: .5rem;
    background: var(--surface-subtle);
    color: var(--muted);
    font-size: .9rem;
  }
  .activity-label { color: var(--text); font-weight: 800; }
  .activity-success { border-left-color: var(--success); background: var(--success-soft); }
  .activity-failure { border-left-color: var(--danger); background: var(--danger-soft); }
  .activity-unavailable { border-left-color: var(--warning); background: var(--warning-soft); }
  .activity-item { white-space: normal; }
  main { min-width: 0; }
  section {
    border: 1px solid var(--border);
    border-radius: .65rem;
    padding: 1rem 1.1rem;
    margin: 1rem 0;
    background: var(--surface);
    box-shadow: var(--shadow);
  }
  h1, h2, h3 { line-height: 1.2; color: var(--text); }
  h1 { margin: 0 0 .65rem; font-size: clamp(1.8rem, 4vw, 2.45rem); letter-spacing: -.025em; }
  h2 { margin-top: 1.5rem; font-size: 1.35rem; }
  section > h2:first-child, section > h3:first-child { margin-top: 0; }
  dl { margin: .4rem 0; }
  dt { font-weight: 750; margin-top: .65rem; color: var(--text); }
  dd { margin-left: 1.25rem; overflow-wrap: anywhere; }
  ol { padding-left: 1.5rem; }
  pre {
    margin: .65rem 0 0;
    padding: .9rem;
    border: 1px solid var(--border);
    border-radius: .4rem;
    background: var(--surface-subtle);
    color: var(--text);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    overflow-x: auto;
    font: .9rem/1.5 ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  }
  form { display: grid; gap: .8rem; margin: .8rem 0 0; }
  label { display: grid; gap: .35rem; font-weight: 650; }
  input, select, button {
    min-height: 2.55rem;
    border: 1px solid var(--border);
    border-radius: .4rem;
    font: inherit;
    padding: .45rem .65rem;
  }
  input, select { width: 100%; color: var(--text); background: var(--surface); }
  button {
    cursor: pointer;
    border-color: transparent;
    color: #fff;
    font-weight: 800;
    box-shadow: 0 2px 5px rgba(0, 0, 0, .15);
  }
  button:hover { filter: brightness(.94); }
  button:active { transform: translateY(1px); }
  .error { color: var(--danger); font-weight: 750; }
  .meta { color: var(--muted); }
  .null, .empty { color: var(--muted); font-family: ui-monospace, monospace; }
  .actions {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: 1rem;
  }
  .actions section {
    margin: 0;
    border-top: .3rem solid var(--action-color);
  }
  .actions h3 { display: flex; align-items: center; gap: .55rem; }
  .action-icon { font-size: 1.25em; }
  .actions button { background: var(--action-color); }
  .action-configure { --action-color: #2563a9; }
  .action-scan { --action-color: #087f8c; }
  .action-prepare { --action-color: #a86300; }
  .action-recover { --action-color: #7552a8; }
  .action-approve { --action-color: #18794e; }
  .action-reject { --action-color: #b42332; }
  .action-publish { --action-color: #c44f13; }
  .stream {
    box-shadow: none;
    margin: 1rem 0;
    border-left-width: .35rem;
  }
  .stream h3 { margin-bottom: .55rem; }
  .stream-stdout { border-left-color: var(--stdout); background: var(--stdout-soft); }
  .stream-stderr { border-left-color: var(--stderr); background: var(--stderr-soft); }
  .stream-stdout h3, .stream-stdout summary { color: var(--stdout); }
  .stream-stderr h3, .stream-stderr summary { color: var(--stderr); }
  details.stream {
    border: 1px solid var(--border);
    border-left-width: .35rem;
    border-radius: .65rem;
    padding: 0;
    overflow: hidden;
  }
  details.stream > summary {
    cursor: pointer;
    padding: .85rem 1rem;
    font-weight: 800;
  }
  details.stream[open] > summary { border-bottom: 1px solid var(--border); }
  details.stream > pre { margin: 1rem; }
  .stream-size { margin-left: .45rem; color: var(--muted); font-size: .82rem; font-weight: 500; }

  @media (max-width: 600px) {
    body { padding-inline: .75rem; }
    .site-header { margin-inline: -.75rem; padding-inline: .75rem; }
    .activity { align-items: flex-start; flex-direction: column; }
    dd { margin-left: .5rem; }
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --page: #0e1522;
      --surface: #172131;
      --surface-subtle: #202c3d;
      --text: #e8edf5;
      --muted: #aab5c6;
      --border: #3b485b;
      --link: #8fc2ff;
      --focus: #72a7ff;
      --success: #62d49b;
      --success-soft: #153c2d;
      --warning: #f0bd65;
      --warning-soft: #443316;
      --danger: #ff8995;
      --danger-soft: #4b2028;
      --stdout: #6bd7a2;
      --stdout-soft: #15372b;
      --stderr: #ff929d;
      --stderr-soft: #432229;
      --shadow: 0 8px 24px rgba(0, 0, 0, .22);
    }
    .action-configure { --action-color: #397fc3; }
    .action-scan { --action-color: #168f9b; }
    .action-prepare { --action-color: #a96a0e; }
    .action-recover { --action-color: #8060b2; }
    .action-approve { --action-color: #23875a; }
    .action-reject { --action-color: #bd3543; }
    .action-publish { --action-color: #bd521e; }
  }
</style>
</head>
<body>
<header class="site-header">
  <nav aria-label="Primary navigation"><a class="brand" href="/">Release Manager Review</a><a href="/">Release status</a><a href="/audit">Audit history</a></nav>
  ${renderRecentActivity()}
</header>
<main>
${body}
</main>
</body>
</html>`;
}

function sendHtml(response, statusCode, title, body) {
  const document = layout(title, body);
  response.writeHead(statusCode, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(document),
    'Cache-Control': 'no-store'
  });
  response.end(document);
}

function runCli(args) {
  return new Promise(resolve => {
    let stdout = '';
    let stderr = '';
    let child;
    let settled = false;

    const finish = result => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    try {
      child = spawn(CLI_EXECUTABLE, args, {
        cwd: CLI_CWD,
        env: process.env,
        stdio: ['ignore', 'pipe', 'pipe']
      });
    } catch (error) {
      finish({
        exitCode: null,
        stdout,
        stderr,
        error: error && error.message ? error.message : String(error)
      });
      return;
    }

    child.stdout.on('data', chunk => { stdout += chunk.toString(); });
    child.stderr.on('data', chunk => { stderr += chunk.toString(); });

    child.once('error', error => {
      finish({
        exitCode: null,
        stdout,
        stderr,
        error: error && error.message ? error.message : String(error)
      });
    });

    child.once('close', code => {
      finish({
        exitCode: typeof code === 'number' ? code : null,
        stdout,
        stderr,
        error: null
      });
    });
  });
}

function renderProcessStream(name, value) {
  const stream = String(value);
  const escaped = escapeHtml(stream);
  const streamClass = name === 'stdout' ? 'stream-stdout' : 'stream-stderr';

  if (stream.length > COLLAPSIBLE_OUTPUT_THRESHOLD) {
    return `<details class="stream ${streamClass}">
      <summary>${name}<span class="stream-size">${stream.length} characters — expand output</span></summary>
      <pre>${escaped}</pre>
    </details>`;
  }

  return `<section class="stream ${streamClass}"><h3>${name}</h3><pre>${escaped}</pre></section>`;
}

function renderProcessResult(result) {
  return `<dl>
    <dt>Exit code</dt><dd>${result.exitCode === null ? 'null' : escapeHtml(result.exitCode)}</dd>
    <dt>Start error</dt><dd>${result.error === null ? 'null' : escapeHtml(result.error)}</dd>
  </dl>
  ${renderProcessStream('stdout', result.stdout)}
  ${renderProcessStream('stderr', result.stderr)}`;
}

function appendAudit(args, result) {
  const entry = {
    timestamp: new Date().toISOString(),
    command: {
      executable: CLI_EXECUTABLE,
      arguments: args.slice(),
      cwd: CLI_CWD
    },
    result: {
      exitCode: result.exitCode,
      stdout: result.stdout,
      stderr: result.stderr,
      error: result.error
    }
  };

  return new Promise((resolve, reject) => {
    let line;
    try {
      line = `${JSON.stringify(entry)}\n`;
    } catch (error) {
      reject(error);
      return;
    }
    fs.appendFile(AUDIT_PATH, line, { encoding: 'utf8' }, error => {
      if (error) reject(error);
      else resolve(entry);
    });
  });
}

function readRequestBody(request, maximumBytes = 1024 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    let failed = false;

    request.on('data', chunk => {
      if (failed) return;
      size += chunk.length;
      if (size > maximumBytes) {
        failed = true;
        reject(new Error('Request body exceeds the maximum allowed size'));
        return;
      }
      chunks.push(chunk);
    });
    request.on('end', () => {
      if (!failed) resolve(Buffer.concat(chunks).toString('utf8'));
    });
    request.on('error', error => {
      if (!failed) {
        failed = true;
        reject(error);
      }
    });
  });
}

function renderMainPage(status) {
  const categories = [
    ['Repository', ['repository', 'repo']],
    ['Scan evidence', ['scanEvidence', 'scanResult', 'scan-evidence', 'scan_evidence']],
    ['Prepared pack', ['preparedPack', 'preparedReleasePack', 'releasePack', 'prepared-pack', 'prepared_pack']],
    ['Changelog', ['changelog', 'changeLog']],
    ['Release Notes', ['releaseNotes', 'notes']],
    ['Announcement', ['announcement']],
    ['Evidence Links', ['evidenceLinks', 'evidenceUrls']],
    ['Approval or Rejection State', ['approvalState', 'rejectionState', 'approval', 'rejection', 'decision', 'reviewState', 'approved', 'rejected']],
    ['Publication Result', ['publicationResult', 'publication', 'publishResult', 'published']]
  ];

  const sections = categories.map(([heading, keys]) =>
    `<section><h2>${escapeHtml(heading)}</h2>${renderValue(findStatusValue(status, keys))}</section>`
  ).join('');

  return `<h1>Release Manager Review</h1>
  <p class="meta">Workflow state below was obtained from the Release Manager CLI status command.</p>
  ${sections}
  <section><h2>Complete Status Output</h2>${renderValue(status)}</section>
  <h2>Actions</h2>
  <div class="actions">
    <section class="action-configure">
      <h3><span class="action-icon" aria-hidden="true">⚙</span>Configure</h3>
      <form method="post" action="/configure" enctype="application/x-www-form-urlencoded">
        <label>Repository <input type="text" name="repo" placeholder="owner/name" required></label>
        <button type="submit">Configure</button>
      </form>
    </section>
    <section class="action-scan">
      <h3><span class="action-icon" aria-hidden="true">⌕</span>Scan</h3>
      <form method="post" action="/scan" enctype="application/x-www-form-urlencoded">
        <button type="submit">Scan</button>
      </form>
    </section>
    <section class="action-prepare">
      <h3><span class="action-icon" aria-hidden="true">▣</span>Prepare</h3>
      <form method="post" action="/prepare" enctype="application/x-www-form-urlencoded">
        <label>Bump
          <select name="bump">
            <option value="patch">patch</option>
            <option value="minor">minor</option>
            <option value="major">major</option>
          </select>
        </label>
        <button type="submit">Prepare</button>
      </form>
    </section>
    <section class="action-recover">
      <h3><span class="action-icon" aria-hidden="true">↻</span>Recover</h3>
      <form method="post" action="/recover" enctype="application/x-www-form-urlencoded">
        <button type="submit">Recover</button>
      </form>
    </section>
    <section class="action-approve">
      <h3><span class="action-icon" aria-hidden="true">✓</span>Approve</h3>
      <form method="post" action="/approve" enctype="application/x-www-form-urlencoded">
        <label>Approver <input type="text" name="approver" required></label>
        <button type="submit">Approve</button>
      </form>
    </section>
    <section class="action-reject">
      <h3><span class="action-icon" aria-hidden="true">✕</span>Reject</h3>
      <form method="post" action="/reject" enctype="application/x-www-form-urlencoded">
        <button type="submit">Reject</button>
      </form>
    </section>
    <section class="action-publish">
      <h3><span class="action-icon" aria-hidden="true">▲</span>Publish</h3>
      <form method="post" action="/publish" enctype="application/x-www-form-urlencoded">
        <button type="submit">Publish</button>
      </form>
    </section>
  </div>`;
}

async function handleStatus(response) {
  const args = ['release-manager.js', 'status'];
  const result = await runCli(args);

  if (result.error !== null || result.exitCode !== 0) {
    sendHtml(response, 500, 'Status command failed',
      `<h1 class="error">Status command failed</h1>
       <p>The Release Manager status subprocess did not complete successfully.</p>
       ${renderProcessResult(result)}`);
    return;
  }

  let status;
  try {
    status = JSON.parse(result.stdout);
  } catch (error) {
    sendHtml(response, 500, 'Invalid status JSON',
      `<h1 class="error">Invalid status JSON</h1>
       <p>${escapeHtml(error && error.message ? error.message : String(error))}</p>
       ${renderProcessResult(result)}`);
    return;
  }

  sendHtml(response, 200, 'Release Manager Review', renderMainPage(status));
}

async function handleAction(response, action, args) {
  const result = await runCli(args);
  let auditError = null;

  try {
    await appendAudit(args, result);
  } catch (error) {
    auditError = error;
  }

  const subprocessFailed = result.error !== null || result.exitCode !== 0;
  const failed = subprocessFailed || auditError !== null;
  const auditMessage = auditError
    ? `<section><h2 class="error">Audit write failed</h2><pre>${escapeHtml(auditError.message || String(auditError))}</pre></section>`
    : '<p>One result entry was appended to the audit log.</p>';

  sendHtml(response, failed ? 500 : 200, `${action} result`,
    `<h1>${escapeHtml(action)} Result</h1>
     ${subprocessFailed ? '<p class="error">The subprocess did not complete successfully.</p>' : '<p>The subprocess completed successfully.</p>'}
     <section>${renderProcessResult(result)}</section>
     ${auditMessage}
     <p><a href="/">Return to release status</a> | <a href="/audit">View audit history</a></p>`);
}

async function handleAudit(response) {
  let contents;
  try {
    contents = await fs.promises.readFile(AUDIT_PATH, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      contents = '';
    } else {
      sendHtml(response, 500, 'Audit read failed',
        `<h1 class="error">Audit read failed</h1><pre>${escapeHtml(error.message || String(error))}</pre>`);
      return;
    }
  }

  const validEntries = [];
  for (const line of contents.split(/\n/)) {
    if (line.length === 0) continue;
    try {
      validEntries.push(JSON.parse(line));
    } catch (_error) {
      // Malformed lines are not audit entries and are omitted from the display.
    }
  }
  validEntries.reverse();

  const entries = validEntries.map((entry, index) =>
    `<section><h2>Entry ${index + 1}</h2>${renderValue(entry)}</section>`
  ).join('');

  sendHtml(response, 200, 'Audit History',
    `<h1>Audit History</h1>
     <p class="meta">Most recently appended entries are shown first.</p>
     ${entries || '<p>No action entries have been recorded.</p>'}`);
}

async function route(request, response) {
  const url = new URL(request.url, `http://${HOST}:${PORT}`);

  if (request.method === 'GET' && url.pathname === '/') {
    await handleStatus(response);
    return;
  }

  if (request.method === 'GET' && url.pathname === '/audit') {
    await handleAudit(response);
    return;
  }

