async function allocatePort() {
  return new Promise((resolve, reject) => {
    const listener = net.createServer();
    listener.once('error', reject);
    listener.listen(0, '127.0.0.1', () => {
      const selected = listener.address().port;
      listener.close(error => error ? reject(error) : resolve(selected));
    });
  });
}

async function canConnect() {
  return new Promise(resolve => {
    const socket = net.createConnection({ host: '127.0.0.1', port });
    let finished = false;
    const finish = result => {
      if (finished) return;
      finished = true;
      socket.destroy();
      resolve(result);
    };
    socket.setTimeout(150, () => finish(false));
    socket.once('connect', () => finish(true));
    socket.once('error', () => finish(false));
  });
}

async function startServer(environment = {}) {
  const existing = process.env.NODE_OPTIONS ? `${process.env.NODE_OPTIONS} ` : '';
  const child = spawn(process.execPath, ['server.js'], {
    cwd: root,
    env: {
      ...process.env,
      NODE_OPTIONS: `${existing}--require=${preloadFile}`,
      REVIEW_UI_TEST_PORT: String(port),
      REVIEW_UI_INHERITED_SENTINEL: 'inherited-verifier-value',
      ...environment
    },
    stdio: ['ignore', 'pipe', 'pipe']
  });
  let output = '';
  child.stdout.on('data', chunk => { output += chunk; });
  child.stderr.on('data', chunk => { output += chunk; });

  const deadline = Date.now() + 5000;
  while (Date.now() < deadline) {
    if (child.exitCode !== null) throw new Error(`server exited early (${child.exitCode}): ${output}`);
    if (await canConnect()) return child;
    await new Promise(resolve => setTimeout(resolve, 35));
  }
  child.kill('SIGKILL');
  throw new Error(`server failed to listen: ${output}`);
}

async function stopServer(child) {
  if (!child || child.exitCode !== null) return;
  const exited = new Promise(resolve => child.once('exit', resolve));
  child.kill('SIGTERM');
  const timer = setTimeout(() => child.kill('SIGKILL'), 1000);
  await exited;
  clearTimeout(timer);
}

async function request(method, pathname, body, headers = {}) {
  const payload = body === undefined ? null : Buffer.from(body, 'utf8');
  return new Promise((resolve, reject) => {
    const req = http.request({
      host: '127.0.0.1', port, method, path: pathname,
      headers: { ...(payload ? { 'content-length': payload.length } : {}), ...headers }
    }, response => {
      const chunks = [];
      response.on('data', chunk => chunks.push(chunk));
      response.on('end', () => resolve({
        statusCode: response.statusCode,
        headers: response.headers,
        body: Buffer.concat(chunks).toString('utf8')
      }));
    });
    req.once('error', reject);
    if (payload) req.write(payload);
    req.end();
  });
}

function post(pathname, fields = {}) {
  return request('POST', pathname, new URLSearchParams(fields).toString(), {
    'content-type': 'application/x-www-form-urlencoded; charset=UTF-8'
  });
}

function attribute(tag, name) {
  const match = tag.match(new RegExp(`\\b${name}\\s*=\\s*(?:(["'])(.*?)\\1|([^\\s>]+))`, 'i'));
  return match ? (match[2] === undefined ? match[3] : match[2]) : null;
}

function decodeText(html) {
  return html
    .replace(/<style\b[\s\S]*?<\/style\s*>/gi, ' ')
    .replace(/<script\b[\s\S]*?<\/script\s*>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#(?:39|x27);/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function formFor(html, route) {
  const all = [...html.matchAll(/<form\b[^>]*>[\s\S]*?<\/form\s*>/gi)].map(match => match[0]);
  const form = all.find(candidate => attribute(candidate.match(/^<form\b[^>]*>/i)[0], 'action') === route);
  assert.ok(form, `missing form for ${route}`);
  const opening = form.match(/^<form\b[^>]*>/i)[0];
  assert.equal((attribute(opening, 'method') || 'get').toLowerCase(), 'post', `${route} must remain POST`);
  return form;
}

function sharedStatusArea(html) {
  const regions = [...html.matchAll(/<(header|nav)\b[^>]*>[\s\S]*?<\/\1\s*>/gi)].map(match => match[0]);
  assert.ok(regions.length, 'layout must contain a shared header or navigation region');
  const activity = regions.find(region => /recent|activity|last\s+action|no\s+activity/i.test(decodeText(region)));
  assert.ok(activity, 'header/navigation does not contain the recent-activity indicator');
  return activity;
}

function styleText(html) {
  const styles = [...html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style\s*>/gi)].map(match => match[1]);
  assert.ok(styles.length, 'layout must embed a style element');
  return styles.join('\n');
}

function invocationsFrom(text) {
  return text.split('\n').filter(Boolean).map(line => JSON.parse(line));
}

async function invocations() {
