function submitControl(form) {
  const button = form.match(/<button\b[^>]*>[\s\S]*?<\/button\s*>/i);
  if (button) return button[0];
  const input = [...form.matchAll(/<input\b[^>]*>/gi)]
    .map(match => match[0])
    .find(tag => /^(?:submit|image)$/i.test(attribute(tag, 'type') || ''));
  assert.ok(input, 'form lacks a submit control');
  return input;
}

function visualSignature(action, form, css) {
  const opening = form.match(/^<form\b[^>]*>/i)[0];
  const control = submitControl(form);
  const controlOpening = control.match(/^<[^>]+>/)[0];
  const visible = decodeText(control) || attribute(controlOpening, 'value') || '';
  const iconRemainder = visible.replace(new RegExp(action, 'ig'), '').replace(/[\s\-_:]/g, '');
  const inline = [attribute(opening, 'style'), attribute(controlOpening, 'style')].filter(Boolean).join(';');
  const tokens = [
    attribute(opening, 'class'), attribute(opening, 'id'),
    attribute(controlOpening, 'class'), attribute(controlOpening, 'id')
  ].filter(Boolean).join(' ');
  const rules = [...css.matchAll(/([^{}]+)\{([^{}]*)\}/g)]
    .filter(match => new RegExp(`(?:^|[-_.#\\s"'=])${action}(?:$|[-_.#\\s"'\\]])`, 'i').test(match[1]))
    .map(match => match[2].replace(/\s+/g, ' ').trim())
    .filter(rule => /(?:color|background|border|content|box-shadow)/i.test(rule));
  assert.ok(iconRemainder || inline || rules.length, `${action} has no observable individual icon/color treatment`);
  return JSON.stringify({ iconRemainder, inline, tokens, rules });
}

