test('all action routes preserve request shapes, exact CLI ordering, environment, HTTP outcomes, and audit results', async () => {
  const cases = [
    ['/configure', { repo: 'owner/repo + space; $(not-shell)' }, ['configure', '--repo', 'owner/repo + space; $(not-shell)']],
    ['/scan', {}, ['scan']],
    ['/prepare', { bump: 'minor' }, ['prepare', '--bump', 'minor']],
    ['/recover', {}, ['recover']],
    ['/approve', { approver: 'Ada Lovelace' }, ['approve', '--approver', 'Ada Lovelace']],
    ['/reject', {}, ['reject']],
    ['/publish', {}, ['publish']]
  ];

  for (const [index, [route, fields, args]] of cases.entries()) {
    const action = args[0];
    const expected = {
      stdout: `route-${index}-${action}-stdout`,
      stderr: `route-${index}-${action}-stderr`,
      exitCode: index === 5 ? 27 : 0
    };
    await writeConfig({ [action]: expected });
    const callsBefore = (await invocations()).length;
    const auditBefore = (await auditEntries()).length;
    const response = await post(route, fields);
    assert.equal(response.statusCode, expected.exitCode === 0 ? 200 : 500);
    assert.ok(decodeText(response.body).includes(expected.stdout));
    assert.ok(decodeText(response.body).includes(expected.stderr));
    assert.match(decodeText(response.body), new RegExp(`exit\\s*(?:code)?[^0-9-]*${expected.exitCode}`, 'i'));
    const calls = await invocations();
    assert.equal(calls.length, callsBefore + 1, `${route} invoked the CLI an unexpected number of times`);
    assertInvocation(calls.at(-1), args);
    const audits = await auditEntries();
    assert.equal(audits.length, auditBefore + 1, `${route} did not append exactly one audit result`);
    assertAudit(audits.at(-1), args, { ...expected, error: null });
  }
});

test('process page independently collapses large, labeled, escaped stdout and stderr streams', async () => {
  const stdoutMarker = '<stdout-tag data-x="one">& STDOUT ONLY \'quoted\'</stdout-tag>';
  const stderrMarker = '<stderr-tag data-x="two">& STDERR ONLY \'quoted\'</stderr-tag>';
  const stdout = `${stdoutMarker}\n${'O'.repeat(100000)}`;
  const stderr = `${stderrMarker}\n${'E'.repeat(100000)}`;
  const expected = { stdout, stderr, exitCode: 23 };
  await writeConfig({ scan: expected });
  const callsBefore = (await invocations()).length;
  const auditBefore = (await auditEntries()).length;
  const response = await post('/scan');
  assert.equal(response.statusCode, 500);
  assert.doesNotMatch(response.body, /<stdout-tag\b|<stderr-tag\b/i, 'stream text was emitted as unsafe HTML');
  assert.doesNotMatch(response.body, /<script\b/i);

  const details = [...response.body.matchAll(/<details\b[^>]*>[\s\S]*?<\/details\s*>/gi)].map(match => match[0]);
  const stdoutRegion = details.find(region => /stdout/i.test(decodeText(region)) && decodeText(region).includes(stdoutMarker));
  const stderrRegion = details.find(region => /stderr/i.test(decodeText(region)) && decodeText(region).includes(stderrMarker));
  assert.ok(stdoutRegion, 'large stdout is not in its own labeled native details control');
  assert.ok(stderrRegion, 'large stderr is not in its own labeled native details control');
  assert.notEqual(stdoutRegion, stderrRegion, 'stdout and stderr share one collapsible control');
  assert.match(stdoutRegion, /<summary\b[^>]*>[\s\S]*stdout[\s\S]*?<\/summary>/i);
  assert.match(stderrRegion, /<summary\b[^>]*>[\s\S]*stderr[\s\S]*?<\/summary>/i);
  assert.ok(!decodeText(stdoutRegion).includes(stderrMarker), 'stderr was merged into stdout');
  assert.ok(!decodeText(stderrRegion).includes(stdoutMarker), 'stdout was merged into stderr');

  const calls = await invocations();
  assert.equal(calls.length, callsBefore + 1, 'large-output request invoked the CLI an unexpected number of times');
  assertInvocation(calls.at(-1), ['scan']);
  const audits = await auditEntries();
  assert.equal(audits.length, auditBefore + 1, 'large-output request did not append exactly one audit result');
  const latest = audits.at(-1);
  assertAudit(latest, ['scan'], { ...expected, error: null });

  const statusText = decodeText(sharedStatusArea(response.body));
  assert.match(statusText, /scan/i);
  assert.match(statusText, /(?:exit\s*(?:code)?|code)[^0-9-]*23/i);
  assert.ok(statusText.includes(latest.timestamp) || statusText.includes(latest.timestamp.slice(0, 19)));

  const auditPage = await request('GET', '/audit');
  const auditStatus = decodeText(sharedStatusArea(auditPage.body));
  assert.match(auditStatus, /scan/i);
  assert.match(auditStatus, /(?:exit\s*(?:code)?|code)[^0-9-]*23/i);
  assert.ok(auditStatus.includes(latest.timestamp) || auditStatus.includes(latest.timestamp.slice(0, 19)));
});

