    await fsp.writeFile(auditFile, `${JSON.stringify(initialAuditEntry)}\n`, 'utf8');
    server = await startServer();
  }
});

test('implementation remains zero-dependency and server-rendered', async () => {
  const pkg = JSON.parse(await fsp.readFile(packageFile, 'utf8'));
  for (const key of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
    assert.ok(!pkg[key] || Object.keys(pkg[key]).length === 0, `${key} must remain empty`);
  }
  const source = await fsp.readFile(serverFile, 'utf8');
  assert.doesNotMatch(source, /<script\b/i, 'server.js emits client-side script');
  assert.doesNotMatch(source, /<link\b[^>]*rel\s*=\s*["']?stylesheet/i, 'server.js emits an external stylesheet');
  assert.doesNotMatch(source, /https?:\/\/[^\s"']+\.css\b/i, 'server.js references remote CSS');
});
